import 'academic_knowledge_unit_catalog.dart';

/// Subject-aware lesson blueprints for the global TOFAN academic library.
/// These are original instructional structures, not copied university text.
class AcademicLessonSpec {
  const AcademicLessonSpec({
    required this.title,
    required this.topic,
    required this.definition,
    required this.content,
    required this.terms,
    required this.examples,
    required this.applications,
  });

  final String title;
  final String topic;
  final String definition;
  final String content;
  final List<String> terms;
  final List<String> examples;
  final List<String> applications;
}

class AcademicCourseLessonBlueprints {
  const AcademicCourseLessonBlueprints._();

  static List<AcademicLessonSpec> forCourse(String courseName, List<String> knowledgeUnitIds) {
    final n = courseName.toLowerCase();

    if (n.contains('python') || n.contains('البرمجة 1') || n == 'البرمجة') {
      return _python(courseName);
    }
    if (n.contains('خوارز') || n.contains('هياكل البيانات')) return _algorithms(courseName);
    if (n.contains('قواعد البيانات') || n.contains('نمذجة البيانات') || n.contains('هندسة البيانات')) return _data(courseName);
    if (n.contains('تعلم الآلة')) return _ml(courseName);
    if (n.contains('ذكاء اصطناعي') || n.contains('ai')) return _ai(courseName);
    if (n.contains('شبك')) return _network(courseName);
    if (n.contains('نظم التشغيل') || n.contains('أنظمة التشغيل')) return _os(courseName);
    if (n.contains('أمن') || n.contains('تشفير') || n.contains('cyber')) return _security(courseName);
    if (n.contains('هندسة البرمجيات') || n.contains('اختبار البرمجيات') || n.contains('devops') || n.contains('إدارة الإصدارات')) return _software(courseName);
    if (n.contains('ويب')) return _web(courseName);
    if (n.contains('معمار') || n.contains('منطق رقمي') || n.contains('معالجات') || n.contains('برمجة منخفضة')) return _architecture(courseName);
    if (n.contains('رسوميات') || n.contains('واقع افتراضي') || n.contains('واقع معزز')) return _graphics(courseName);
    if (n.contains('تفاعل') || n.contains('تجربة المستخدم') || n.contains('قابلية الاستخدام') || n.contains('hci')) return _hci(courseName);
    if (n.contains('إحصاء') || n.contains('احتمال')) return _statistics(courseName);
    if (n.contains('رياضيات') || n.contains('منطق')) return _math(courseName);
    if (n.contains('سحاب')) return _cloud(courseName);
    if (n.contains('مضمن') || n.contains('إنترنت الأشياء') || n.contains('زمنية')) return _embedded(courseName);
    if (n.contains('مشروع التخرج')) return _capstone(courseName);
    if (n.contains('أخلاقيات') || n.contains('المهنة') || n.contains('المجتمع')) return _ethics(courseName);
    return _domain(courseName, knowledgeUnitIds);
  }

  static AcademicLessonSpec _s(String title, String topic, String definition, String content, List<String> terms, List<String> examples, List<String> applications) =>
      AcademicLessonSpec(title: title, topic: topic, definition: definition, content: content, terms: terms, examples: examples, applications: applications);

