  static List<AcademicLessonSpec> _domain(String c, List<String> unitIds) {
    final units = unitIds.map(AcademicKnowledgeUnitCatalog.byId).whereType<AcademicKnowledgeUnit>().toList();
    final focus = units.isEmpty ? 'المفاهيم الأساسية في $c' : units.first.arabicName;
    return List<AcademicLessonSpec>.generate(6, (i) {
      final stage = ['الأساس المفاهيمي','البنية والمكونات','التطبيق الموجه','التحليل والمقارنة','التصميم والتحقق','التكامل والمشروع'][i];
      return _s(
        '$stage في $c',
        '$focus — $stage',
        'هذا الدرس يعرّف «$focus» داخل مقرر «$c» ويربط المعرفة بالتطبيق والتحقق.',
        'يدرس الطالب «$focus» داخل سياق «$c»، ثم يحدد المكونات والعلاقات والافتراضات والقيود. في التطبيق يحول المفهوم إلى حالة قابلة للملاحظة، ويقارن البدائل ويختبر النتيجة. في المرحلة الأخيرة يربط أكثر من مفهوم في حل صغير موثق، مع فصل الدليل عن الاستنتاج وتحديد ما يحتاج إلى تحقق إضافي.',
        [focus, 'تحليل', 'تطبيق', 'تحقق', 'قيود'],
        ['حالة تطبيقية في $c', 'مقارنة بديلين مرتبطين بـ$focus'],
        ['التطبيق العملي في $c', 'مشروع مصغر مرتبط بوحدات المعرفة'],
      );
    });
  }
